/**
 * @file HalI2cBmp581Comm.h
 * @brief The Bmp581 driver's port on a `BaseI2c`, and the one mapping of its errors.
 *
 * Every port hook comes from `hf::HalI2cCommBase`. Add a hook here only when the driver needs one
 * the base does not have; for control pins chain `hf::HalGpioCommBase` (HalGpioCommBase.h).
 *
 * Generated by tools/new_handler.py from templates/handler/.
 */
#pragma once

#include <cstdint>

#include "bmp581.hpp"

#include "hf/iiw/Status.h"

#include "HalI2cCommBase.h"

namespace hf {

class HalI2cBmp581Comm;

/// The driver's port base, instantiated for the adapter.
using Bmp581Port = bmp581::BusInterface<HalI2cBmp581Comm>;

/// `bmp581::BusInterface` on a `BaseI2c`.
class HalI2cBmp581Comm final : public HalI2cCommBase<HalI2cBmp581Comm, Bmp581Port> {
public:
  using HalI2cCommBase::HalI2cCommBase;
};

/**
 * @brief `hf::Status` for a Bmp581 driver error (standards/errors.md, driver errors).
 *
 * Every enumerator is listed and there is no `default`, so a value the driver adds later is a
 * -Wswitch error here. Chip-specific values are documented on the handler's page.
 */
[[nodiscard]] constexpr Status ToStatus(bmp581::DriverError error) noexcept {
  switch (error) {
  case bmp581::DriverError::None:
    return Status::Ok;
  case bmp581::DriverError::InvalidParameter:
    return Status::InvalidArgument;
  case bmp581::DriverError::NotInitialized:
    return Status::NotInitialized;
  case bmp581::DriverError::Bus:
    return Status::Bus;
  case bmp581::DriverError::InvalidChipId:
    return Status::NotFound;
  case bmp581::DriverError::NvmNotReady:
    return Status::Busy;
  case bmp581::DriverError::PorSoftReset:
    return Status::Fault;
  case bmp581::DriverError::InvalidPowerMode:
    return Status::InvalidArgument;
  case bmp581::DriverError::NvmInvalidAddr:
    return Status::InvalidArgument;
  case bmp581::DriverError::NvmCommandError:
    return Status::Fault;
  }
  return Status::Unknown;
}

/// A driver result as an `hf::Result`, with the driver's error value as detail.
template <typename T>
[[nodiscard]] constexpr Result<T> ToResult(const bmp581::DriverResult<T>& r) noexcept {
  return {r.value, ToStatus(r.error), static_cast<uint16_t>(r.error)};
}

/// A driver result without a value as an `hf::Result<void>`.
[[nodiscard]] constexpr Result<void> ToResult(const bmp581::DriverResult<void>& r) noexcept {
  return {ToStatus(r.error), static_cast<uint16_t>(r.error)};
}

} // namespace hf
